extern "C" int strlen(const char *);
class stringx;
class string_buf {
  void *data;
  int ref_count;
public:
  int char_length;
};
class stringx {
  void *chars;
public:
  string_buf *my_buf;
  stringx();
  stringx(const stringx &);
  ~stringx();
  void make_room(int);
  void append(const stringx &);
  void append(const char *, int = -1);
};
inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const stringx &lhs, const char *rhs) {
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}
class script_instance {
  char gap[12];
  stringx name;
public:
  const stringx &get_name() const { return name; }
};
class vm_executable {
  stringx fullname;
public:
  const stringx &get_fullname() const { return fullname; }
};
class vm_thread {
  script_instance *inst;
  const vm_executable *ex;
public:
  script_instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};
class vm_stack {
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char *, int);
};
class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack &, entry_t);
  };
};
class entity;
class entity_widget {
  char gap[324];
  entity *ent;
public:
  entity *get_ent() const { return ent; }
};
typedef entity *vm_entity_t;
typedef entity_widget *vm_entity_widget_t;
void error(const stringx &);
class slf_entity_widget_get_entity_t : public script_library_class::function {
public:
  struct parms_t { vm_entity_widget_t me; };
  virtual bool operator()(vm_stack &stack, entry_t entry);
};
bool slf_entity_widget_get_entity_t::operator()(vm_stack& stack,entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_entity_t result = parms->me->get_ent();
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
